manifest={'version':version,'draft':True,'acceptanceText':'Li e aceito os Termos de Uso e a Política de Privacidade da EvoluFit.','healthConsentText':'Autorizo o tratamento de peso, altura, medidas e registros de exercícios que informo para personalizar sugestões gerais e acompanhar minha rotina na EvoluFit. Esta autorização é específica para esses dados de saúde, não inclui publicidade e pode ser revogada pelo canal de privacidade.', 'healthConsentVersion':'health-tracking-2026-10-18.1','documents':{}}
for key,slug,title,body in [('terms','termos','Termos de Uso',terms),('privacy','privacidade','Política de Privacidade',privacy)]:
 article=f'<article class="legal-document" data-legal-kind="{key}" data-legal-version="{version}"><p class="legal-version">Versão {version} · Elaborada em 18/10/2026 · Minuta</p>'+common+body+'</article>'
 digest=hashlib.sha256(article.encode()).hexdigest()
 for path,base in [(f'legal/{version}/{slug}.html','../../'),(f'{slug}.html','')]:
  page=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="{csp}"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#173c2b"><title>{title} • EvoluFit</title><link rel="icon" href="{base}media/elephant-logo.png"><script src="{base}theme.js?v=18"></script><link rel="stylesheet" href="{base}legal.css?v=legal1"><link rel="stylesheet" href="{base}theme.css?v=18"></head><body class="legal-page"><header class="legal-page-header"><a href="{base}sobre.html">EvoluFit</a><nav aria-label="Documentos"><a href="{base}termos.html">Termos de Uso</a><a href="{base}privacidade.html">Política de Privacidade</a><a href="{base}conta.html">Entrar</a></nav></header><main>{article}</main><footer>Documentos da EvoluFit · Consulte o responsável pelos campos pendentes.</footer></body></html>'''
  Path(path).write_text(page)
 manifest['documents'][key]={'version':version,'sha256':digest,'path':f'legal/{version}/{slug}.html','title':title,'body':article}
Path('work/legal-18/documents.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
public={**manifest,'documents':{key:{k:v for k,v in doc.items() if k!='body'} for key,doc in manifest['documents'].items()}}
Path('legal-manifest.json').write_text(json.dumps(public,ensure_ascii=False,indent=2)+'\n')
Path('legal-manifest.js').write_text("'use strict';\nwindow.EvoluiLegalManifest=Object.freeze("+json.dumps(public,ensure_ascii=False,separators=(',',':'))+');\n')
print('Documentos completos e versões SHA-256 preparados.')
